import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`digital-product-launch`,heroTitle:`Scale your digital sales in minutes`,heroSubtitle:`Perplexity Computer researches your niche, analyzes competitor pricing, and builds your full growth plan - automatically.`,inputUrlCta:`Build my launch plan`,inputUrlPlaceholder:`yourproduct.com`,inputUrlPrefill:`Go to {url} and build a complete digital product launch plan. 1) Research the niche - identify the target audience, their pain points, and what content or products already exist in this space. 2) Find and analyze 10+ competitors - what they charge, how they position their offers, what their sales pages look like, and where they have gaps. 3) Develop a pricing strategy with three tiers (or a recommended single price point) based on competitor analysis and perceived value. 4) Write full sales page copy - headline, subheadline, bullet points, testimonials framework, objection handling, guarantee section, and CTA. 5) Create a 7-day email launch sequence - subject lines, full body copy for each email, send timing, and the psychological trigger each email uses (urgency, social proof, transformation, etc.). 6) Build a post-launch nurture flow - 5 emails for buyers (onboarding, engagement, upsell) and 5 emails for non-buyers (objection handling, case studies, downsell). 7) Deliver everything in a structured document with a launch timeline, day-by-day checklist, and all copy ready to paste into your email platform and sales page builder.`,heroOverlaySteps:[`Researching your niche, audience, and market landscape`,`Analyzing competitor pricing, positioning, and sales pages`,`Writing sales page copy and 7-day email launch sequence`,`Launch plan, pricing strategy, and nurture flows - ready to execute`],generatingSteps:[`Visiting {url} to extract your product, niche, and positioning`,`Designing an agent to research competitors, pricing, and market gaps`,`Configuring sales copy generation, email sequences, and pricing models`,`Setting up your complete launch plan with timeline and day-by-day checklist`],featureSectionTitle:`From product idea to launch plan`,featureCardTitles:[`Connects to your course stack`,`Outputs you can launch with`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Google Docs, Google Sheets, Notion, Canva - Computer plugs into your tools so launch copy flows straight from research to your platforms.`,`Complete sales page copy. 7-day email launch sequence. Pricing strategy with competitor benchmarks. Post-launch nurture flows for buyers and non-buyers. Day-by-day launch checklist.`],capabilitySectionTitle:`Your launch team, on autopilot`,capabilitySectionSubtitle:`Paste your product URL, step away, come back to a complete launch plan.`,capabilityCards:[{title:`Niche Research`,description:`Computer can map your target audience, their pain points, and the existing competitive landscape - so your launch is built on real market data.`},{title:`Competitor Analysis`,description:`Computer can analyze 10+ competitors - their pricing, sales page structure, and positioning gaps - and show you exactly where to differentiate.`},{title:`Sales Copy & Emails`,description:`Computer can write your full sales page, a 7-day launch email sequence, and post-launch nurture flows - with subject lines, body copy, and send timing.`},{title:`Connect Your Tools`,description:`Computer can push deliverables to Gmail, Google Docs, Notion, Google Sheets, and more - build workflows across your entire launch stack.`},{title:`Remember & Refine`,description:`Computer can remember your brand voice, audience insights, and past launch performance - so every campaign gets sharper over time.`},{title:`Monitor & Alert`,description:`Computer can track competitor pricing changes and new product launches in your niche - and alert you when it's time to adjust your strategy.`}]});export{t as default};
